{
  "findings": [
    {
      "check_id": "CKV_AZURE_149",
      "title": "Azure Virtual Machine Scale Set does not have automatic OS image patching enabled",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "The azurerm_windows_virtual_machine_scale_set resource does not have automatic OS image patching enabled, which can leave the VMs vulnerable to security risks."
    }
  ],
  "patched_code": "resource \"azurerm_windows_virtual_machine_scale_set\" \"negative4\" {\n  name                 = \"negative4-vmss\"\n  resource_group_name  = azurerm_resource_group.negative4.name\n  location             = azurerm_resource_group.negative4.location\n  sku                  = \"Standard_F2\"\n  computer_name_prefix = \"vm-\"\n\n  encryption_at_host_enabled = true\n\n  patch_mode = \"AutomaticByOS\"\n}",
  "fix_summary": "Enabled automatic OS image patching for the Azure Virtual Machine Scale Set by setting patch_mode to 'AutomaticByOS'."
}
